class Solution {
    public int findCircleNum(int[][] M) {
        if (M == null) {
            return 0;
        }
        int n = M.length;
        int count = 0;

        Queue<Integer> queue = new LinkedList<>();
        boolean visited[] = new boolean[n];

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                queue.offer(i);
                while(!queue.isEmpty()) {
                    int s = queue.poll();
                    visited[s] = true;
                    for (int j = 0; j < n; j++) {
                        if (M[s][j] == 1 && !visited[j]) {
                            queue.offer(j);
                            visited[j] = true;
                        }
                    }
                }
                count++;
            }
        }
        return count;
    }
}
