var (
	mark []int
)

func findCircleNum(m [][]int) int {
	//	边界检查
	if m == nil || len(m) == 0 {
		return 0
	}
	//	初始化
	ans := 0
	mark = make([]int, len(m))
	for i := 0; i < len(m); i++ {
		if mark[i] == 0 {
			ans++
			dfs(m,i)
		}
	}
	return ans
}
func dfs(m [][]int, i int) {
	for j:=0;j<len(m);j++{
		if m[i][j] == 1 && mark[j] == 0 {
			mark[j] = 1
			if i==j{
				continue
			}
			dfs(m,j)
		}
	}
}

