    public int findCircleNum(int[][] isConnected) {
        int n = isConnected.length;
        UnionFind dsu = new UnionFind(n);
        int numberOfComponents = n;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isConnected[i][j] == 1 && dsu.find(i) != dsu.find(j)) {
                    numberOfComponents--;
                    dsu.union_set(i, j);
                }
            }
        }

        return numberOfComponents;
    }
}

//Approach 1: Using dfs and without using any visited array for that
//Editorial: https://leetcode.com/problems/number-of-provinces/discuss/376612/Easy-C++-DFS-Solution/1038941
class Solution {
public:
    void dfs(vector<vector<int>> &grid,int i,int n)
    {
        for(int j=0;j<n;j++)
        {
            if(grid[i][j])
            {
                grid[i][j]=0;
                grid[j][i]=0;
                dfs(grid,j,n);
            }
        }
    }
    int findCircleNum(vector<vector<int>>& grid) {
        int n=grid.size();
        int ans=0;
        for(int i=0;i<n;i++)
        {
            if(grid[i][i])
            {
                dfs(grid,i,n);
                ans+=1;
            }
        }
        return ans;
    }
};
//Approach 2: Using dsu
//Editorial: https://leetcode.com/problems/number-of-provinces/discuss/873741/Simple-C%2B%2B-Solution-oror-Fully-Explained-at-begineers-level-oror-Easy-Understanding-of-UNION-concept
class Solution {
public:
    vector<int> parent;
    int findparent(int n)
    {
        if(parent[n]==-1)
            return n;
        return parent[n]=findparent(parent[n]);
    }
    void _union(int x,int y)
    {
        int px=findparent(x);
        int py=findparent(y);
        if(px==py)
            return;
        parent[px]=py;
    }
    int findCircleNum(vector<vector<int>>& grid) {
        int n=grid.size();
        parent=vector<int> (n,-1);
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<n;j++)
            {
                if(grid[i][j])
                    _union(i,j);
            }
        }
        int ans=0;
        for(auto it:parent)
        {
            if(it==-1)
                ans+=1;
        }
        return ans;
    }
};

# DFS
class Solution(object):
    def findCircleNum(self, isConnected):
        """
        :type isConnected: List[List[int]]
        :rtype: int
        """
        n = len(isConnected)
        vis = [False] * n

        def dfs(i):
            vis[i] = True
            for j in range(n):
                if isConnected[i][j] == 1 and not vis[j]:
                    dfs(j)

        ans = 0
        for i in range(n):
            if not vis[i]:
                dfs(i)
                ans += 1
        return ans
